create extension if not exists pgcrypto;create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,name text,location text,niche text,tone text,hooks text,emojis text,cta text,created_at timestamptz default now(),updated_at timestamptz default now());create table if not exists trends(id uuid primary key default gen_random_uuid(),title text not null,category text,platform text,country text,heat integer default 0,growth integer default 0,freshness timestamptz default now(),summary text,source_url text,created_at timestamptz default now());create table if not exists generations(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,type text not null,niche text,language text,profile_dna jsonb,output text,created_at timestamptz default now());alter table profiles enable row level security;alter table trends enable row level security;alter table generations enable row level security;create policy "public trends readable" on trends for select using(true);create policy "users read own profile" on profiles for select using(auth.uid()=id);create policy "users insert own profile" on profiles for insert with check(auth.uid()=id);create policy "users update own profile" on profiles for update using(auth.uid()=id);create policy "users read own generations" on generations for select using(auth.uid()=user_id);create policy "users insert own generations" on generations for insert with check(auth.uid()=user_id);